from typing import List

class Solution:
    def countCompleteSubarrays(self, nums: List[int]) -> int:
        n = len(nums)
        D = len(set(nums))
        count = 0
        for i in range(n):
            seen = {}
            j = i
            # find smallest j such that nums[i..j] has D distinct values
            while j < n and len(seen) < D:
                seen[nums[j]] = seen.get(nums[j], 0) + 1
                j += 1
            if len(seen) == D:
                # subarrays [i..k] for k in [j-1, n-1] are complete
                count += n - (j - 1)
            else:
                break
        return count
