from collections import defaultdict

class Solution:
    def countCompleteSubarrays(self, nums: List[int]) -> int:
        n = len(nums)
        k = len(set(nums))
        cnt = defaultdict(int)
        distinct = 0
        right = 0  # window is [left, right)
        result = 0
        for left in range(n):
            while right < n and distinct < k:
                if cnt[nums[right]] == 0:
                    distinct += 1
                cnt[nums[right]] += 1
                right += 1
            if distinct == k:
                # minimal end index is right-1
                result += n - (right - 1)
            else:
                break
            # remove nums[left]
            cnt[nums[left]] -= 1
            if cnt[nums[left]] == 0:
                distinct -= 1
        return result
