class Solution:
    def countCompleteSubarrays(self, nums: List[int]) -> int:
        n = len(nums)
        k = len(set(nums))
        count = {}
        r = 0  # window is nums[l:r]
        distinct = 0
        result = 0
        for l in range(n):
            # extend r until window has k distinct
            while r < n and distinct < k:
                x = nums[r]
                if count.get(x, 0) == 0:
                    distinct += 1
                count[x] = count.get(x, 0) + 1
                r += 1
            if distinct == k:
                # window nums[l:r] has k distinct; subarrays [l, e] for e >= r-1 are complete
                result += n - (r - 1)
            # remove nums[l]
            x = nums[l]
            count[x] -= 1
            if count[x] == 0:
                distinct -= 1
        return result

