import json
from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(1, 8))
    kind = draw(st.integers(0, 4))
    if kind == 0:
        # all equal elements
        v = draw(st.integers(1, 2000))
        nums = [v] * n
    elif kind == 1:
        # sorted ascending with duplicates
        nums = sorted(draw(st.lists(st.integers(1, 6), min_size=n, max_size=n)))
    elif kind == 2:
        # reverse sorted
        nums = sorted(draw(st.lists(st.integers(1, 6), min_size=n, max_size=n)), reverse=True)
    elif kind == 3:
        # extremes of value range (scaled down: small and large values)
        nums = draw(st.lists(st.sampled_from([1, 2, 1999, 2000]), min_size=n, max_size=n))
    else:
        nums = draw(st.lists(st.integers(1, 6), min_size=n, max_size=n))
    return json.dumps(nums)

def validate(inp):
    try:
        s = inp.strip()
        nums = json.loads(s)
    except Exception:
        return False
    if not isinstance(nums, list):
        return False
    if not (1 <= len(nums) <= 1000):
        return False
    for x in nums:
        if not isinstance(x, int) or isinstance(x, bool):
            return False
        if not (1 <= x <= 2000):
            return False
    return True

def ref(inp):
    nums = json.loads(inp.strip())
    n = len(nums)
    total = len(set(nums))
    count = 0
    for i in range(n):
        for j in range(i, n):
            if len(set(nums[i:j + 1])) == total:
                count += 1
    return json.dumps(count)
